  1	'use client';
  2	import { useIsoLayoutEffect } from '@base-ui/utils/useIsoLayoutEffect';
  3	import { useRefWithInit } from '@base-ui/utils/useRefWithInit';
  4	import { useFieldRootContext } from '../field-root-context/FieldRootContext';
  5	import type { FieldControlRegistration } from './useFieldControlRegistration';
  6	
  7	export function useRegisterFieldControl(
  8	  controlRef: FieldControlRegistration['controlRef'],
  9	  id: FieldControlRegistration['id'],
 10	  value: FieldControlRegistration['value'],
 11	  getFormValueOverride?: FieldControlRegistration['getValue'],
 12	  enabled = true,
 13	  name?: FieldControlRegistration['name'],
 14	) {
 15	  const { registerFieldControl } = useFieldRootContext();
 16	  const sourceRef = useRefWithInit(() => Symbol());
 17	
 18	  // Re-register without unregistering first: re-registration with the same id updates the
 19	  // form's fields Map entry in place, while a delete + re-add would move the field to the
 20	  // end of the Map every time its value changes.
 21	  useIsoLayoutEffect(() => {
 22	    const source = sourceRef.current;
 23	
 24	    if (!enabled) {
 25	      registerFieldControl(source, undefined);
 26	      return;
 27	    }
 28	
 29	    const registration: FieldControlRegistration = {
 30	      controlRef,
 31	      getValue: getFormValueOverride,
 32	      id,
 33	      name,
 34	      value,
 35	    };
 36	
 37	    registerFieldControl(source, registration);
 38	  }, [controlRef, enabled, getFormValueOverride, id, name, registerFieldControl, sourceRef, value]);
 39	
 40	  useIsoLayoutEffect(() => {
 41	    const source = sourceRef.current;
 42	    return () => {
 43	      registerFieldControl(source, undefined);
 44	    };
 45	  }, [registerFieldControl, sourceRef]);
 46	}
 47	'use client';
 48	import * as React from 'react';
 49	import { useIsoLayoutEffect } from '@base-ui/utils/useIsoLayoutEffect';
 50	import { useStableCallback } from '@base-ui/utils/useStableCallback';
 51	import { getCombinedFieldValidityData } from '../../field/utils/getCombinedFieldValidityData';
 52	import { useFormContext } from '../form-context/FormContext';
 53	import type { FieldValidityData } from '../../field/root/FieldRoot';
 54	
 55	export interface FieldControlRegistration {
 56	  controlRef: React.RefObject<any>;
 57	  id: string | undefined;
 58	  name?: string | undefined;
 59	  getValue?: (() => unknown) | undefined;
 60	  value: unknown;
 61	}
 62	
 63	export function useFieldControlRegistration(params: UseFieldControlRegistrationParameters) {
 64	  const {
 65	    commit,
 66	    invalid,
 67	    markedDirtyRef,
 68	    name,
 69	    setRegisteredFieldName,
 70	    registeredFieldIdRef,
 71	    setValidityData,
 72	    validityData,
 73	  } = params;
 74	
 75	  const { formRef } = useFormContext();
 76	
 77	  const activeFieldControlSourceRef = React.useRef<symbol | null>(null);
 78	  const registrationRef = React.useRef<FieldControlRegistration | null>(null);
 79	  const initialValueCapturedRef = React.useRef(false);
 80	
 81	  const getValueForForm = useStableCallback(() => {
 82	    const registration = registrationRef.current;
 83	    if (!registration) {
 84	      return undefined;
 85	    }
 86	
 87	    if (registration.getValue) {
 88	      return registration.getValue();
 89	    }
 90	
 91	    return registration.value;
 92	  });
 93	
 94	  function getRegistrationValue(registration: FieldControlRegistration) {
 95	    return registration.value === undefined ? getValueForForm() : registration.value;
 96	  }
 97	
 98	  const validate = useStableCallback(() => {
 99	    const registration = registrationRef.current;
100	    markedDirtyRef.current = true;
101	
102	    if (!registration) {
103	      commit(validityData.value);
104	      return;
105	    }
106	
107	    commit(getRegistrationValue(registration));
108	  });
109	
110	  function refreshRegistration() {
111	    const registration = registrationRef.current;
112	    if (!registration || !registration.id) {
113	      return;
114	    }
115	
116	    formRef.current.fields.set(registration.id, {
117	      getValue: getValueForForm,
118	      name: name ?? registration.name,
119	      controlRef: registration.controlRef,
120	      validityData: getCombinedFieldValidityData(validityData, invalid),
121	      validate,
122	    });
123	  }
124	
125	  function deleteRegistration(id = registrationRef.current?.id) {
126	    if (id) {
127	      formRef.current.fields.delete(id);
128	    }
129	  }
130	
131	  // The baseline belongs to the field, not to a control instance: registration re-runs on every
132	  // value change, and a control that unmounts and remounts (or is swapped for another one) comes
133	  // back as a brand new registration. Capturing more than once would turn whichever value the
134	  // control happens to hold at that point into the initial value, so a modified field would read
135	  // pristine and its real initial value would read dirty. Consumers that want a fresh baseline
136	  // remount or key `<Field.Root>` itself.
137	  function captureInitialValue(registration: FieldControlRegistration) {
138	    if (initialValueCapturedRef.current) {
139	      return;
140	    }
141	
142	    initialValueCapturedRef.current = true;
143	    const initialValue = getRegistrationValue(registration);
144	
145	    setValidityData((prev) =>
146	      prev.initialValue === initialValue ? prev : { ...prev, initialValue },
147	    );
148	  }
149	
150	  useIsoLayoutEffect(() => {
151	    const registration = registrationRef.current;
152	    if (!registration || !registration.id) {
153	      return;
154	    }
155	
156	    setRegisteredFieldName(name ? undefined : registration.name);
157	
158	    formRef.current.fields.set(registration.id, {
159	      getValue: getValueForForm,
160	      name: name ?? registration.name,
161	      controlRef: registration.controlRef,
162	      validityData: getCombinedFieldValidityData(validityData, invalid),
163	      validate,
164	    });
165	  }, [formRef, getValueForForm, invalid, name, setRegisteredFieldName, validate, validityData]);
166	
167	  useIsoLayoutEffect(() => {
168	    const fields = formRef.current.fields;
169	
170	    return () => {
171	      const id = registrationRef.current?.id;
172	      if (id) {
173	        fields.delete(id);
174	      }
175	    };
176	  }, [formRef]);
177	
178	  const register = useStableCallback(
179	    (source: symbol, registration: FieldControlRegistration | undefined) => {
180	      if (!registration) {
181	        if (activeFieldControlSourceRef.current === source) {
182	          activeFieldControlSourceRef.current = null;
183	          deleteRegistration();
184	          registrationRef.current = null;
185	          setRegisteredFieldName(undefined);
186	          registeredFieldIdRef.current = undefined;
187	        }
188	        return;
189	      }
190	
191	      const previousId = registrationRef.current?.id;
192	
193	      activeFieldControlSourceRef.current = source;
194	      registrationRef.current = registration;
195	      if (!name) {
196	        setRegisteredFieldName(registration.name);
197	      }
198	      registeredFieldIdRef.current = registration.id;
199	
200	      if (previousId && previousId !== registration.id) {
201	        deleteRegistration(previousId);
202	      }
203	
204	      captureInitialValue(registration);
205	      refreshRegistration();
206	    },
207	  );
208	
209	  return [validate, register] as const;
210	}
211	
212	export interface UseFieldControlRegistrationParameters {
213	  commit: (value: unknown) => void;
214	  invalid: boolean;
215	  markedDirtyRef: React.RefObject<boolean>;
216	  name: string | undefined;
217	  setRegisteredFieldName: (name: string | undefined) => void;
218	  registeredFieldIdRef: React.RefObject<string | undefined>;
219	  setValidityData: React.Dispatch<React.SetStateAction<FieldValidityData>>;
220	  validityData: FieldValidityData;
221	}
222	export function serializeValue(value: unknown): string {
223	  if (value == null) {
224	    return '';
225	  }
226	  if (typeof value === 'string') {
227	    return value;
228	  }
229	  try {
230	    return JSON.stringify(value);
231	  } catch {
232	    return String(value);
233	  }
234	}

